import React from "react";
import styled from "styled-components";
import { ButtonFooter, ButtonFooterSpacer } from "@mendix/ide-ui-components/button/ButtonFooter";
import { Button } from "@mendix/ide-ui-components/button/Button";
import { HelpButton } from "@mendix/ide-ui-components/button/HelpButton";

const StyledFooter = styled(ButtonFooter)`
    margin-top: auto;
    padding: 16px 0 0 0;
    background-color: transparent;
`;

interface DialogFooterProps {
    onOk?: () => void;
    onCancel?: () => void;
    onHelp?: () => void;
    okLabel?: string;
    cancelLabel?: string;
    showHelp?: boolean;
}

const DialogFooter: React.FC<DialogFooterProps> = ({
    onOk,
    onCancel,
    onHelp,
    okLabel = "OK",
    cancelLabel = "Cancel",
    showHelp = true,
}) => {
    return (
        <StyledFooter>
            {showHelp && <HelpButton onPress={onHelp} />}
            <ButtonFooterSpacer />
            <Button variant="primary" onPress={onOk}>
                {okLabel}
            </Button>
            <Button onPress={onCancel}>{cancelLabel}</Button>
        </StyledFooter>
    );
};

export default DialogFooter;
